import{_ as t,c as a,o as r,ag as o}from"./chunks/framework.Ce1dNOE6.js";const u=JSON.parse('{"title":"palette","description":"","frontmatter":{},"headers":[],"relativePath":"api/core/palette.md","filePath":"api/core/palette.md","lastUpdated":1785055892000}'),l={name:"api/core/palette.md"};function s(n,e,i,d,p,h){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="palette" tabindex="-1">palette <a class="header-anchor" href="#palette" aria-label="Permalink to &quot;palette&quot;">​</a></h1><p>Color engine for Basalt: more than 16 colors on a 16-color terminal.</p><p>Every color that can appear on screen is an entry in a global registry (index 0-255). Indices 0-15 are the native CC colors; palette.rgb() registers custom colors above that. The render buffer stores registry indices as raw bytes. At flush time a per-terminal Mapper assigns the 16 hardware palette slots to whatever registry colors are actually visible:</p><ul><li>native colors always keep their own slot,</li><li>custom colors take over the slots of native colors that are NOT currently on screen (via term.setPaletteColour),</li><li>anything beyond 16 simultaneous colors falls back to the nearest currently-assigned color. Slot assignments are sticky between frames to avoid palette flicker.</li></ul><h2 id="types" tabindex="-1">Types <a class="header-anchor" href="#types" aria-label="Permalink to &quot;Types&quot;">​</a></h2><h3 id="palettetranslationmap" tabindex="-1"><code>PaletteTranslationMap</code> <a class="header-anchor" href="#palettetranslationmap" aria-label="Permalink to &quot;`PaletteTranslationMap`&quot;">​</a></h3><div class="language-lua vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">lua</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PaletteTranslationMap </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> table</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">string, string</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><h3 id="paletteusedcolors" tabindex="-1"><code>PaletteUsedColors</code> <a class="header-anchor" href="#paletteusedcolors" aria-label="Permalink to &quot;`PaletteUsedColors`&quot;">​</a></h3><div class="language-lua vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">lua</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PaletteUsedColors </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> table</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">integer, boolean</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><h3 id="paletteterminal" tabindex="-1"><code>PaletteTerminal</code> <a class="header-anchor" href="#paletteterminal" aria-label="Permalink to &quot;`PaletteTerminal`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>setPaletteColour <em>(optional)</em></td><td><code>fun(color: number, r: number, g: number, b: number)</code></td><td></td></tr><tr><td>setPaletteColor <em>(optional)</em></td><td><code>fun(color: number, r: number, g: number, b: number)</code></td><td></td></tr><tr><td>getPaletteColour <em>(optional)</em></td><td><code>fun(color: number): number, number, number</code></td><td></td></tr><tr><td>getPaletteColor <em>(optional)</em></td><td><code>fun(color: number): number, number, number</code></td><td></td></tr></tbody></table><h3 id="mapper" tabindex="-1"><code>Mapper</code> <a class="header-anchor" href="#mapper" aria-label="Permalink to &quot;`Mapper`&quot;">​</a></h3><hr><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>term</td><td><code>PaletteTerminal</code></td><td>Terminal controlled by this mapper</td></tr><tr><td>overridden</td><td><code>table&lt;integer, integer&gt;</code></td><td>Registry index loaded into each overridden slot</td></tr><tr><td>prevSlot</td><td><code>table&lt;integer, integer&gt;</code></td><td>Previous hardware slot per registry index</td></tr><tr><td>prevMap</td><td><code>PaletteTranslationMap</code></td><td>Previous byte-to-blit translation</td></tr></tbody></table><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h2><h3 id="palette-getrgb-value" tabindex="-1">palette.getRGB(value) <a class="header-anchor" href="#palette-getrgb-value" aria-label="Permalink to &quot;palette.getRGB(value)&quot;">​</a></h3><p>Resolves a registry byte/index or public color handle to RGB floats.</p><ul><li><p><strong>value</strong> (<code>string|number</code>) Registry byte, registry index, or colors.* handle</p></li><li><p><strong>returns</strong> <strong>r</strong> (<code>number</code>)</p></li><li><p><strong>returns</strong> <strong>g</strong> (<code>number</code>)</p></li><li><p><strong>returns</strong> <strong>b</strong> (<code>number</code>)</p></li></ul><h3 id="palette-rgb-r-g-b" tabindex="-1">palette.rgb(r, g, b) <a class="header-anchor" href="#palette-rgb-r-g-b" aria-label="Permalink to &quot;palette.rgb(r, g, b)&quot;">​</a></h3><p>Registers or resolves an RGB color for use by the render buffer.</p><ul><li><p><strong>r</strong> (<code>number|string</code>) Red component or #RRGGBB string</p></li><li><p><strong>g</strong> (<code>number</code>, optional) Green component</p></li><li><p><strong>b</strong> (<code>number</code>, optional) Blue component</p></li><li><p><strong>returns</strong> <strong>color</strong> (<code>number</code>)</p></li></ul><h3 id="palette-hasvirtual" tabindex="-1">palette.hasVirtual() <a class="header-anchor" href="#palette-hasvirtual" aria-label="Permalink to &quot;palette.hasVirtual()&quot;">​</a></h3><p>Returns whether custom palette colors are currently registered.</p><ul><li><strong>returns</strong> <strong>hasCustomColors</strong> (<code>boolean</code>)</li></ul><h3 id="palette-windowtranslation-win" tabindex="-1">palette.windowTranslation(win) <a class="header-anchor" href="#palette-windowtranslation-win" aria-label="Permalink to &quot;palette.windowTranslation(win)&quot;">​</a></h3><p>Builds a blit-hex -&gt; registry-byte translation for a hosted CC window. Returns nil when the window palette is untouched (identity is cheaper).</p><ul><li><p><strong>win</strong> (<code>PaletteTerminal</code>) CC window or compatible terminal</p></li><li><p><strong>returns</strong> <strong>translate</strong> (<code>PaletteTranslationMap|nil</code>)</p></li></ul><h3 id="palette-newmapper-t" tabindex="-1">palette.newMapper(t) <a class="header-anchor" href="#palette-newmapper-t" aria-label="Permalink to &quot;palette.newMapper(t)&quot;">​</a></h3><p>Creates a palette mapper for one terminal.</p><ul><li><p><strong>t</strong> (<code>PaletteTerminal</code>) Terminal-like object</p></li><li><p><strong>returns</strong> <strong>mapper</strong> (<code>Mapper</code>)</p></li></ul><h3 id="mapper-build-used" tabindex="-1">Mapper:build(used) <a class="header-anchor" href="#mapper-build-used" aria-label="Permalink to &quot;Mapper:build(used)&quot;">​</a></h3><p>Assigns hardware palette slots for the colors used by this frame.</p><ul><li><p><strong>used</strong> (<code>PaletteUsedColors</code>) Registry indices used by this frame</p></li><li><p><strong>returns</strong> <strong>map</strong> (<code>PaletteTranslationMap</code>) Registry byte to terminal blit character</p></li><li><p><strong>returns</strong> <strong>changed</strong> (<code>boolean</code>)</p></li></ul><h3 id="mapper-restore" tabindex="-1">Mapper:restore() <a class="header-anchor" href="#mapper-restore" aria-label="Permalink to &quot;Mapper:restore()&quot;">​</a></h3><p>Restores terminal palette colors changed by this mapper.</p>',35)])])}const g=t(l,[["render",s]]);export{u as __pageData,g as default};
